"""The Void world level art: sky (day/night), far, middle and ground layers (two painted sets).
img(name) gives the surface; scaled(name, w, h) a cached resized copy."""
import base64
import io
import pygame

GROUND_GRASS = 38              # rows above the ground line in void_ground.png
SOLID_ROWS = {'void_far': 177, 'void_mid': 170, 'void_ground': 43}
PNG = {
  'void_far': ('png', ''),
  'void_ground': ('png', ''),
  'void_mid': ('png', ''),
  'void_sky_day': ('jpg', ''),
  'void_sky_night': ('jpg', ''),
}
_C = {}


def has(name):
  return name in PNG


def img(name):
  s = _C.get(name)
  if s is None:
    ext, data = PNG[name]
    s = pygame.image.load(io.BytesIO(base64.b64decode(data)), 'art.' + ext)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def scaled(name, w, h, smooth=True):
  k = (name, int(w), int(h))
  s = _C.get(k)
  if s is None:
    src = img(name)
    fn = getattr(pygame.transform, 'smoothscale', None) if smooth else None
    try:
      s = (fn or pygame.transform.scale)(src, (max(1, int(w)), max(1, int(h))))
    except Exception:
      s = pygame.transform.scale(src, (max(1, int(w)), max(1, int(h))))
    _C[k] = s
  return s
